mapper.select:
select
u.status != 'DELETED'
and ur.role_code = #{criteria.roleCodeFilter}
and (u.login_id like concat('%', #{criteria.filter}, '%') or u.employee_no like concat('%', #{criteria.filter}, '%') or k.name like concat('%', #{criteria.filter}, '%') or r.role_name like concat('%', #{criteria.filter}, '%'))
order by ur.status, ur.assignment_type, u.user_id, ur.role_code limit #{criteria.safeSize} offset #{criteria.offset}

select count(*) from user_roles
where user_id = #{userId}
  and role_code = #{roleCode}
  and status = 'ACTIVE'

      and assignment_id != #{assignmentId}


      and valid_start_date <= #{validEndDate}


      and valid_start_date <= DATE '9999-12-31'

  and coalesce(valid_end_date, DATE '9999-12-31') >= #{validStartDate}
